#!/usr/bin/env python3
# /// script
# name: resolve-repo-context
# purpose: Resolve and verify worktree content authority and shared Git coordination authority.
# inputs: ["argv: --repo-root PATH? --config PATH --mode read|write"]
# outputs: ["stdout: JSON repository/worktree context"]
# requires-python = ">=3.10"
# dependencies: []
# contexts: [A, B, C, E]
# network: false
# write-scope: none
# ///
from __future__ import annotations

import argparse
import hashlib
import os
import re
import sys
from pathlib import Path
from typing import Any

from _common import ContractError, contained, dump, git, load_json, stable_id


DEFAULT_CONTENT_ROOTS = {
    "issues": "issues",
    "tasks": "tasks",
    "specifications": "specs",
    "architecture": "architecture",
    "features": "features",
    "documents": "docs",
    "system_spec": "system-spec",
}
DEFAULT_LOCAL_STATE = {
    "graph": ".dev-graph/state/graph.json",
    "cache": ".dev-graph/cache",
    "locks": ".dev-graph/locks",
}
GITHUB_REMOTE = re.compile(
    r"^(?:https?://github\.com/|ssh://git@github\.com/|git@github\.com:)([^/]+)/(.+?)(?:\.git)?/?$",
    re.IGNORECASE,
)


def discover(explicit: str | None) -> tuple[Path, str]:
    choices: list[tuple[str, str]] = []
    if explicit:
        choices.append((explicit, "explicit --repo-root"))
    trusted = os.environ.get("CLAUDE_PROJECT_DIR")
    if trusted:
        choices.append((trusted, "CLAUDE_PROJECT_DIR"))
    cp = __import__("subprocess").run(
        ["git", "rev-parse", "--show-toplevel"], text=True, capture_output=True, check=False
    )
    if cp.returncode == 0:
        choices.append((cp.stdout.strip(), "git toplevel"))
    for parent in (Path.cwd(), *Path.cwd().parents):
        if (parent / ".git").exists() or (parent / ".dev-graph").is_dir():
            choices.append((str(parent), "cwd marker"))
            break
    if not choices:
        raise ContractError("repository root cannot be resolved")
    root = Path(choices[0][0]).expanduser().resolve(strict=True)
    actual = Path(git(["rev-parse", "--show-toplevel"], root)).resolve(strict=True)
    if root != actual:
        raise ContractError(f"selected root is not current worktree root: {root} != {actual}")
    if trusted and Path(trusted).expanduser().resolve(strict=True) != root:
        raise ContractError("--repo-root and CLAUDE_PROJECT_DIR disagree")
    return root, choices[0][1]


def repository_id_for(remote: str, common: Path) -> str:
    """Derive the durable repository identity from the canonical authority."""
    match = GITHUB_REMOTE.fullmatch(remote.strip()) if remote else None
    if match:
        owner, repository = match.groups()
        return f"github:{owner}/{repository.removesuffix('.git')}"
    digest = hashlib.sha256(str(common.resolve(strict=True)).encode("utf-8")).hexdigest()
    return f"local:sha256:{digest}"


def _absolute_git_path(raw: str, root: Path) -> Path:
    path = Path(raw)
    return (root / path).resolve(strict=True) if not path.is_absolute() else path.resolve(strict=True)


def verify_common_ownership(root: Path, git_dir: Path, common: Path) -> None:
    """Prove that the selected worktree and common directory are one repository."""
    try:
        objects = _absolute_git_path(git(["rev-parse", "--git-path", "objects"], root), root)
        config = _absolute_git_path(git(["rev-parse", "--git-path", "config"], root), root)
        common_objects = (common / "objects").resolve(strict=True)
        common_config = (common / "config").resolve(strict=True)
    except OSError as exc:
        raise ContractError(f"git common dir authority is incomplete: {common}: {exc}") from exc
    if objects != common_objects:
        raise ContractError("git common dir objects authority does not belong to selected repository")
    if config != common_config:
        raise ContractError("git common dir config authority does not belong to selected repository")
    if git_dir != common:
        marker = git_dir / "commondir"
        if not marker.is_file() or marker.is_symlink():
            raise ContractError(f"worktree git dir has no trusted commondir marker: {marker}")
        try:
            declared = (git_dir / marker.read_text(encoding="utf-8").strip()).resolve(strict=True)
        except OSError as exc:
            raise ContractError(f"invalid worktree commondir marker: {marker}: {exc}") from exc
        if declared != common:
            raise ContractError(f"worktree commondir mismatch: {declared} != {common}")
    root_remote = git(["remote", "get-url", "origin"], root, check=False)
    common_remote = git(["--git-dir", str(common), "remote", "get-url", "origin"], root, check=False)
    if root_remote != common_remote:
        raise ContractError("worktree and git common dir resolve different origin remotes")


def _validate_relative(raw: Any, label: str) -> Path:
    if not isinstance(raw, str) or not raw or "\x00" in raw:
        raise ContractError(f"{label} must be a non-empty repository-relative path")
    relative = Path(raw)
    if relative.is_absolute() or ".." in relative.parts:
        raise ContractError(f"{label} escapes repository authority: {raw}")
    return relative


def resolve_declared_path(root: Path, raw: Any, label: str, *, reject_leaf_symlink: bool) -> Path:
    """Resolve an existing target or its longest existing parent without escaping root."""
    relative = _validate_relative(raw, label)
    candidate = root / relative
    current = root
    for part in relative.parts:
        current = current / part
        if current.is_symlink():
            try:
                target = current.resolve(strict=True)
            except OSError as exc:
                raise ContractError(f"broken content symlink for {label}: {current}: {exc}") from exc
            contained(target, root)
            if reject_leaf_symlink:
                raise ContractError(f"content root path must not traverse a symlink: {label}={current}")
        if not current.exists() and not current.is_symlink():
            break
    try:
        resolved = candidate.resolve(strict=True) if candidate.exists() or candidate.is_symlink() else candidate.resolve(strict=False)
    except OSError as exc:
        raise ContractError(f"cannot resolve {label}: {candidate}: {exc}") from exc
    contained(resolved, root, must_exist=False)
    return resolved


def resolve_config_paths(root: Path, config: dict[str, Any] | None) -> tuple[dict[str, str], dict[str, str]]:
    config = config or {}
    policy = config.get("path_policy") or {}
    if not isinstance(policy, dict):
        raise ContractError("path_policy must be an object")
    forbidden = (
        policy.get("authority") not in {None, "caller-repository"}
        or policy.get("allow_outside_repository") not in {None, False}
        or policy.get("follow_content_symlinks_outside_repository") not in {None, False}
    )
    if forbidden:
        raise ContractError("path_policy weakens caller-repository containment")
    content = config.get("content_roots") or DEFAULT_CONTENT_ROOTS
    local = config.get("local_state") or DEFAULT_LOCAL_STATE
    if not isinstance(content, dict) or not isinstance(local, dict):
        raise ContractError("content_roots and local_state must be objects")
    resolved_content = {
        key: str(resolve_declared_path(root, value, f"content_roots.{key}", reject_leaf_symlink=True))
        for key, value in sorted(content.items())
    }
    resolved_local = {
        key: str(resolve_declared_path(root, value, f"local_state.{key}", reject_leaf_symlink=False))
        for key, value in sorted(local.items())
    }
    return resolved_content, resolved_local


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root")
    parser.add_argument("--config", default=".dev-graph/config.json")
    parser.add_argument("--mode", choices=("read", "write"), default="read")
    args = parser.parse_args()
    root, trust = discover(args.repo_root)
    common_raw = git(["rev-parse", "--git-common-dir"], root)
    common = Path(common_raw)
    if not common.is_absolute():
        common = root / common
    common = common.resolve(strict=True)
    git_dir_raw = git(["rev-parse", "--git-dir"], root)
    git_dir = Path(git_dir_raw)
    if not git_dir.is_absolute():
        git_dir = root / git_dir
    git_dir = git_dir.resolve(strict=True)
    verify_common_ownership(root, git_dir, common)
    remote = git(["remote", "get-url", "origin"], root, check=False)
    repository_id = repository_id_for(remote, common)
    config_arg = Path(args.config)
    if config_arg.is_absolute():
        config_path = contained(config_arg, root, must_exist=False)
    else:
        config_path = root / _validate_relative(args.config, "config")
    config = None
    diagnostics: list[str] = []
    if config_path.exists() or config_path.is_symlink():
        try:
            config_path = contained(config_path, root)
        except OSError as exc:
            raise ContractError(f"broken repository config symlink: {config_path}: {exc}") from exc
        config = load_json(config_path)
        if not isinstance(config, dict):
            raise ContractError("repo config must be a JSON object")
        configured = config.get("repository_id") if isinstance(config, dict) else None
        if configured and configured != repository_id:
            raise ContractError("repo config repository_id does not match derived repository")
    else:
        diagnostics.append("config_missing")
    content_roots, local_state_paths = resolve_config_paths(root, config)
    branch = git(["symbolic-ref", "--quiet", "--short", "HEAD"], root, check=False) or None
    head = git(["rev-parse", "HEAD"], root)
    default_ref = git(["symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"], root, check=False)
    default_branch = default_ref.rsplit("/", 1)[-1] if default_ref else (
        ((config or {}).get("worktrees") or {}).get("default_branch") if isinstance(config, dict) else None
    )
    if not default_branch:
        default_branch = "main"
        diagnostics.append("default_branch_fallback_main")
    worktree_id = stable_id("wt_", repository_id, str(root))
    coord = common / "dev-graph"
    plugin_source = Path(__file__).resolve().parents[1]
    trusted = os.environ.get("CLAUDE_PROJECT_DIR")
    result = {
        "repo_root": str(root), "repository_id": repository_id, "worktree_id": worktree_id,
        "git_common_dir": str(common), "git_dir": str(git_dir), "branch": branch,
        "head_sha": head, "default_branch": default_branch,
        "root_trust_evidence": {"selected_by": trust, "git_toplevel_verified": True,
                                "claude_project_dir_verified": not trusted or Path(trusted).resolve() == root,
                                "git_common_dir_ownership_verified": True},
        "content_roots": {"repository": str(root), **content_roots},
        "local_state_paths": {"config": str(config_path), **local_state_paths},
        "coordination_paths": {"root": str(coord), "leases": str(coord / "leases.json"),
                               "events": str(coord / "events.json")},
        "plugin_source": str(plugin_source), "mode": args.mode, "diagnostics": diagnostics,
    }
    dump(result)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ContractError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        raise SystemExit(1)

#!/usr/bin/env python3
# /// script
# name: upsert-node
# purpose: Atomically add or patch one canonical Markdown artifact and its dev-graph node.
# inputs: ["argv: --repo-root PATH --input JSON [--graph FILE] [--body-file FILE] [--dry-run]"]
# outputs: ["stdout: JSON transaction receipt"]
# requires-python = ">=3.10"
# dependencies: ["validate-graph-schema.py"]
# contexts: [A, B, C, E]
# network: false
# write-scope: one canonical content artifact plus .dev-graph/state/graph.json
# ///
from __future__ import annotations

import argparse
import copy
import fcntl
import hashlib
import importlib.util
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path, PurePosixPath
from typing import Any

from _common import ContractError, atomic_json, contained, dump, load_json, utc_now
from node_transaction import (
    finalize_transaction,
    graph_operation_lock,
    prepare_transaction,
    recover_pending_transaction,
)


PLUGIN_ROOT = Path(__file__).resolve().parents[1]
SCHEMA_PATH = PLUGIN_ROOT / "schemas" / "graph-node.schema.json"
TEMPLATE_CONTRACT_PATH = PLUGIN_ROOT / "templates" / "template-contract.json"
ROOT_BY_KIND = {
    "issue": "issues",
    "task": "tasks",
    "specification": "specs",
    "architecture": "architecture",
    "document": "docs",
    "feature": "features",
}
# feature を生む正経路の出自。manual/github/system-dev-planner は macro 層の入口ではない
# (system-dev-planner は 1 feature → exact-13 task を返す側で、feature 自体は作らない)。
MACRO_FEATURE_ORIGIN_KINDS = frozenset({"generated", "system-spec-harness"})
TEMPLATE_BY_KIND = {
    "issue": "issue.md",
    "task": "task.md",
    "specification": "specification.md",
    "architecture": "architecture.md",
    "document": "document.md",
    "feature": "feature.md",
}


def _validator() -> Any:
    path = Path(__file__).with_name("validate-graph-schema.py")
    spec = importlib.util.spec_from_file_location("dev_graph_node_validator", path)
    if not spec or not spec.loader:
        raise ContractError(f"cannot load canonical validator: {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _atomic_bytes(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp, path)
    finally:
        try:
            os.unlink(temp)
        except FileNotFoundError:
            pass


def _graph_path(root: Path, explicit: str | None) -> Path:
    if explicit:
        candidate = Path(explicit)
        candidate = candidate if candidate.is_absolute() else root / candidate
    else:
        config_path = root / ".dev-graph" / "config.json"
        config = load_json(config_path)
        raw = (config.get("local_state") or {}).get("graph") if isinstance(config, dict) else None
        if not isinstance(raw, str) or not raw:
            raise ContractError(".dev-graph/config.json omits local_state.graph")
        candidate = root / raw
    return contained(candidate, root, must_exist=True)


def _input(path: Path) -> dict[str, Any]:
    payload = load_json(path)
    if not isinstance(payload, dict):
        raise ContractError("node input must be a JSON object")
    return payload


def _json_digest(value: Any) -> str:
    return hashlib.sha256(
        json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode()
    ).hexdigest()


def _git_common_dir(root: Path) -> Path:
    completed = subprocess.run(
        ["git", "-C", str(root), "rev-parse", "--git-common-dir"],
        check=False,
        capture_output=True,
        text=True,
    )
    if completed.returncode:
        raise ContractError(
            "apply-lifecycle-request requires a git repository: "
            f"{(completed.stderr or completed.stdout).strip()}"
        )
    raw = Path(completed.stdout.strip())
    return (raw if raw.is_absolute() else root / raw).resolve(strict=True)


def _lifecycle_coordination_path(
    root: Path,
    raw: str,
    *,
    must_exist: bool,
) -> Path:
    common = _git_common_dir(root)
    authority = (common / "dev-graph" / "completion-receipts").resolve()
    candidate = Path(raw).expanduser().resolve(strict=must_exist)
    try:
        candidate.relative_to(authority)
    except ValueError as exc:
        raise ContractError(
            "lifecycle request/receipt path escapes git-common-dir completion authority"
        ) from exc
    if candidate.parent != authority:
        raise ContractError(
            "lifecycle request/receipt must be a direct completion-receipts child"
        )
    return candidate


def _lifecycle_task_matches(
    graph: dict[str, Any],
    *,
    node_id: str,
    expected_set: dict[str, Any],
) -> dict[str, Any] | None:
    nodes = graph.get("nodes")
    if not isinstance(nodes, list):
        raise ContractError("canonical graph must be an object with nodes[]")
    matches = [
        node
        for node in nodes
        if isinstance(node, dict) and node.get("graph_node_id") == node_id
    ]
    if len(matches) != 1:
        raise ContractError(
            "apply-lifecycle-request target must resolve exactly one graph node"
        )
    node = matches[0]
    if all(node.get(key) == value for key, value in expected_set.items()):
        return node
    return None


def _validate_lifecycle_request(
    root: Path,
    request: dict[str, Any],
) -> tuple[Path, dict[str, Any], dict[str, Any], Path]:
    if (
        request.get("schema_version") != "1.1"
        or request.get("owner") != "C02/run-dev-graph-node"
        or request.get("operation") != "apply-lifecycle-request"
        or request.get("status") != "pending"
    ):
        raise ContractError("lifecycle request identity/status mismatch")
    expected_digest = _json_digest(
        {key: value for key, value in request.items() if key != "request_digest"}
    )
    if request.get("request_digest") != expected_digest:
        raise ContractError("lifecycle request digest mismatch")
    event_key = request.get("event_key")
    if not isinstance(event_key, str) or not event_key:
        raise ContractError("lifecycle request event_key is required")
    raw_graph = request.get("graph_path")
    if (
        not isinstance(raw_graph, str)
        or not raw_graph
        or Path(raw_graph).is_absolute()
        or ".." in Path(raw_graph).parts
    ):
        raise ContractError("lifecycle request graph_path must be repository-relative")
    graph_path = contained(root / raw_graph, root, must_exist=True)
    graph = load_json(graph_path)
    if not isinstance(graph, dict):
        raise ContractError("canonical graph must be an object")
    revision_before = request.get("graph_revision_before")
    if not isinstance(revision_before, int) or revision_before < 0:
        raise ContractError("lifecycle request graph_revision_before is invalid")
    graph_sha_before = request.get("graph_sha256_before")
    if not isinstance(graph_sha_before, str) or not re.fullmatch(
        r"[0-9a-f]{64}", graph_sha_before
    ):
        raise ContractError("lifecycle request graph_sha256_before is invalid")
    task_patch = request.get("task_patch")
    if not isinstance(task_patch, dict):
        raise ContractError("lifecycle request task_patch must be an object")
    node_id = task_patch.get("graph_node_id")
    expected_set = task_patch.get("set")
    if not isinstance(node_id, str) or not node_id:
        raise ContractError("lifecycle request task graph_node_id is required")
    if not isinstance(expected_set, dict):
        raise ContractError("lifecycle request task_patch.set must be an object")
    allowed = {
        "status",
        "updated_at",
        "completion_evidence",
        "pull_request_linkages",
    }
    if set(expected_set) - allowed:
        raise ContractError("lifecycle request task_patch.set contains unsupported fields")
    completion = expected_set.get("completion_evidence")
    if (
        expected_set.get("status") != "done"
        or not isinstance(completion, dict)
        or completion.get("status") != "done"
    ):
        raise ContractError("lifecycle request must project durable done state")
    feature_patch = request.get("feature_patch")
    if feature_patch is not None:
        raise ContractError(
            "built-in apply-lifecycle-request does not accept a feature rollup; "
            "complete the task without --registration-receipt, then run the feature rollup"
        )
    nodes = graph.get("nodes")
    current = next(
        (
            node
            for node in nodes
            if isinstance(node, dict) and node.get("graph_node_id") == node_id
        ),
        None,
    ) if isinstance(nodes, list) else None
    if not isinstance(current, dict):
        raise ContractError("lifecycle request task graph_node_id is not in the graph")
    file_path = task_patch.get("file_path")
    if file_path != current.get("file_path"):
        raise ContractError("lifecycle request task file_path does not match the graph")
    artifact = contained(root / str(file_path), root, must_exist=True)
    artifact_before = task_patch.get("artifact_sha256_before")
    if not isinstance(artifact_before, str) or not re.fullmatch(
        r"[0-9a-f]{64}", artifact_before
    ):
        raise ContractError("lifecycle request artifact_sha256_before is invalid")
    return graph_path, graph, task_patch, artifact


def _apply_lifecycle_request(args: argparse.Namespace) -> dict[str, Any]:
    root = Path(args.repo_root).expanduser().resolve(strict=True)
    if not args.request or not args.receipt:
        raise ContractError(
            "apply-lifecycle-request requires --request and --receipt"
        )
    request_path = _lifecycle_coordination_path(
        root,
        args.request,
        must_exist=True,
    )
    receipt_path = _lifecycle_coordination_path(
        root,
        args.receipt,
        must_exist=False,
    )
    if request_path == receipt_path:
        raise ContractError("lifecycle request and receipt paths must differ")
    request = _input(request_path)
    graph_path, graph, task_patch, artifact = _validate_lifecycle_request(
        root,
        request,
    )
    node_id = str(task_patch["graph_node_id"])
    expected_set = task_patch["set"]
    revision_before = int(request["graph_revision_before"])
    graph_sha_before = str(request["graph_sha256_before"])
    artifact_sha_before = str(task_patch["artifact_sha256_before"])
    current_revision = graph.get("graph_revision")
    current_graph_sha = _sha256(graph_path.read_bytes())
    current_artifact_sha = _sha256(artifact.read_bytes())

    already_applied = (
        current_revision == revision_before + 1
        and _lifecycle_task_matches(
            graph,
            node_id=node_id,
            expected_set=expected_set,
        )
        is not None
    )
    if already_applied:
        if _frontmatter_status(artifact) != "done":
            raise ContractError(
                "lifecycle task graph is done but Markdown frontmatter is not done"
            )
        upsert_receipt = {
            "graph_revision_after": current_revision,
            "graph_sha256_after": current_graph_sha,
            "artifact_sha256_after": current_artifact_sha,
            "idempotent": True,
        }
    else:
        if (
            current_revision != revision_before
            or current_graph_sha != graph_sha_before
            or current_artifact_sha != artifact_sha_before
        ):
            raise ContractError(
                "lifecycle request before-image does not match durable graph/artifact"
            )
        state_dir = root / ".dev-graph" / "state"
        state_dir.mkdir(parents=True, exist_ok=True)
        descriptor, temporary = tempfile.mkstemp(
            prefix=".lifecycle-task-patch.",
            suffix=".json",
            dir=str(state_dir),
        )
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
                json.dump(
                    {
                        "graph_node_id": node_id,
                        "patch": expected_set,
                    },
                    stream,
                    ensure_ascii=False,
                    sort_keys=True,
                )
                stream.flush()
                os.fsync(stream.fileno())
            upsert_receipt = _perform(
                argparse.Namespace(
                    repo_root=str(root),
                    graph=str(graph_path),
                    input=temporary,
                    body_file=None,
                    dry_run=False,
                )
            )
        finally:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
        if (
            upsert_receipt.get("owner") != "C02/run-dev-graph-node"
            or upsert_receipt.get("status") != "applied"
            or upsert_receipt.get("operation") != "updated"
            or upsert_receipt.get("graph_revision_after") != revision_before + 1
        ):
            raise ContractError(
                "C02 lifecycle task upsert did not apply exactly one revision"
            )

    receipt = {
        "schema_version": "1.0",
        "owner": "C02/run-dev-graph-node",
        "operation": "apply-lifecycle-request",
        "status": "applied",
        "event_key": request["event_key"],
        "graph_node_id": node_id,
        "request_digest": request["request_digest"],
        "graph_sha256_after": upsert_receipt["graph_sha256_after"],
        "graph_revision_after": upsert_receipt["graph_revision_after"],
        "task_artifact_sha256_after": upsert_receipt["artifact_sha256_after"],
        "idempotent": bool(upsert_receipt.get("idempotent")),
        "applied_at": utc_now(),
    }
    atomic_json(receipt_path, receipt)
    return receipt


def _frontmatter_status(path: Path) -> str | None:
    text = path.read_text(encoding="utf-8")
    if not text.startswith("---\n"):
        return None
    marker = text.find("\n---\n", 4)
    if marker < 0:
        return None
    for line in text[4:marker].splitlines():
        match = re.match(r"^status:\s*(.*?)\s*$", line)
        if match:
            return match.group(1).strip("\"'")
    return None


def _node_id(node: dict[str, Any]) -> str:
    value = node.get("graph_node_id")
    if not isinstance(value, str) or not value.strip():
        raise ContractError("graph_node_id is required")
    return value


def _canonical_path(node: dict[str, Any], existing: dict[str, Any] | None) -> str:
    kind = node.get("artifact_kind")
    if kind not in ROOT_BY_KIND:
        raise ContractError(f"unsupported artifact_kind: {kind!r}")
    raw = node.get("file_path")
    if raw is None and existing is not None:
        raw = existing.get("file_path")
    if raw is None:
        slug = re.sub(r"[^A-Za-z0-9._-]+", "-", _node_id(node)).strip("-.")
        if not slug:
            raise ContractError("graph_node_id cannot form a canonical file name")
        raw = f"{ROOT_BY_KIND[kind]}/{slug}.md"
        node["file_path"] = raw
    if not isinstance(raw, str):
        raise ContractError("file_path must be a repository-relative Markdown path")
    logical = PurePosixPath(raw)
    if logical.is_absolute() or ".." in logical.parts or logical.suffix != ".md":
        raise ContractError("file_path must be a contained repository-relative .md path")
    if not logical.parts or logical.parts[0] != ROOT_BY_KIND[kind]:
        raise ContractError(f"{kind} must be stored under {ROOT_BY_KIND[kind]}/")
    node["file_path"] = logical.as_posix()
    if existing is not None and existing.get("file_path") != node["file_path"]:
        raise ContractError("upsert does not move an existing node; create an explicit migration")
    return node["file_path"]


def _assert_c14_macro_contract(node: dict[str, Any], root: Path) -> None:
    """feature は C14 macro contract 由来だけを受理する (通常 artifact routing では作らせない)。

    SKILL.md OUT1 / MM 契約: 「feature は C14 の macro contract から受け取り、通常 artifact
    routing で新規生成しない」。この gate が無い間、lineage が manual/全 null の feature が
    通常 add で登録され features/ に実ファイルが作られていた (2026-07-21 live-trial r13)。

    fail-closed: 判定に必要な情報が欠けている場合は必ず ContractError を送出する。
    """
    lineage = node.get("source_lineage")
    if not isinstance(lineage, dict):
        raise ContractError(
            "feature requires source_lineage proving C14 macro contract provenance"
        )

    def source_digest_matches() -> bool:
        """source_path の実ファイル内容が source_digest と一致するかを実測する。"""
        raw = lineage.get("source_path")
        expected = lineage.get("source_digest")
        if not isinstance(raw, str) or not raw or not isinstance(expected, str) or not expected:
            return False
        try:
            source = contained(root / raw, root, must_exist=True)
        except (ContractError, OSError):
            return False
        return _sha256(source.read_bytes()) == expected

    origin_kind = lineage.get("origin_kind")
    if origin_kind not in MACRO_FEATURE_ORIGIN_KINDS:
        raise ContractError(
            "feature must come from the C14 macro contract: "
            f"source_lineage.origin_kind {origin_kind!r} is not one of "
            f"{sorted(MACRO_FEATURE_ORIGIN_KINDS)}"
        )
    source_plugin = lineage.get("source_plugin")
    if not isinstance(source_plugin, str) or not source_plugin.strip():
        raise ContractError(
            "feature from the C14 macro contract requires source_lineage.source_plugin"
        )
    if not source_digest_matches():
        raise ContractError(
            "feature from the C14 macro contract requires source_lineage.source_path to be a "
            "contained repository file whose sha256 equals source_lineage.source_digest"
        )


def _body_from_artifact(path: Path) -> str:
    text = path.read_text(encoding="utf-8")
    if not text.startswith("---\n"):
        raise ContractError(f"existing artifact has no frontmatter: {path}")
    marker = text.find("\n---\n", 4)
    if marker < 0:
        raise ContractError(f"existing artifact frontmatter is not terminated: {path}")
    return text[marker + 5 :].lstrip("\n")


def _body(
    payload: dict[str, Any], body_file: str | None, root: Path,
    artifact: Path, kind: str, existing: dict[str, Any] | None,
) -> str:
    if body_file:
        source = Path(body_file)
        source = source if source.is_absolute() else root / source
        value = contained(source, root, must_exist=True).read_text(encoding="utf-8")
    elif "body" in payload:
        value = payload["body"]
        if not isinstance(value, str):
            raise ContractError("input body must be a string")
    elif existing is not None:
        value = _body_from_artifact(artifact)
    else:
        value = (PLUGIN_ROOT / "templates" / TEMPLATE_BY_KIND[kind]).read_text(encoding="utf-8")
    if value.lstrip().startswith("---"):
        raise ContractError("body must not contain YAML frontmatter; upsert-node owns frontmatter")
    return value.rstrip() + "\n"


def _artifact_bytes(node: dict[str, Any], body: str, schema: dict[str, Any]) -> bytes:
    properties = schema.get("properties") if isinstance(schema, dict) else None
    order = list(properties) if isinstance(properties, dict) else list(node)
    keys = [key for key in order if key in node] + sorted(set(node) - set(order))
    lines = ["---"]
    lines.extend(
        f"{key}: {json.dumps(node[key], ensure_ascii=False, sort_keys=True, separators=(',', ':'))}"
        for key in keys
    )
    lines.extend(["---", "", body.rstrip(), ""])
    return "\n".join(lines).encode("utf-8")


def _request_node(
    payload: dict[str, Any], existing: dict[str, Any] | None,
) -> tuple[dict[str, Any], bool]:
    if "node" in payload and "patch" in payload:
        raise ContractError("input must contain either node or patch, not both")
    if "node" in payload:
        raw = payload["node"]
        if not isinstance(raw, dict):
            raise ContractError("input node must be an object")
        node = copy.deepcopy(raw)
        explicit_updated_at = "updated_at" in raw
    elif "patch" in payload:
        if existing is None:
            raise ContractError("patch requires an existing graph node")
        patch = payload["patch"]
        if not isinstance(patch, dict):
            raise ContractError("input patch must be an object")
        node = copy.deepcopy(existing)
        node.update(copy.deepcopy(patch))
        explicit_updated_at = "updated_at" in patch
    else:
        # A bare canonical node object is accepted for simple callers.
        node = copy.deepcopy(payload)
        node.pop("body", None)
        explicit_updated_at = "updated_at" in node
    now = utc_now()
    if existing is None:
        node.setdefault("created_at", now)
        node.setdefault("updated_at", node["created_at"])
    else:
        node.setdefault("created_at", existing.get("created_at"))
        node.setdefault("updated_at", existing.get("updated_at"))
    return node, explicit_updated_at


def _perform(args: argparse.Namespace) -> dict[str, Any]:
    root = Path(args.repo_root).expanduser().resolve(strict=True)
    graph_path = _graph_path(root, args.graph)
    input_path = Path(args.input)
    input_path = input_path if input_path.is_absolute() else root / input_path
    payload = _input(contained(input_path, root, must_exist=True))
    validator = _validator()
    schema = load_json(SCHEMA_PATH)
    contract = load_json(TEMPLATE_CONTRACT_PATH)
    if not isinstance(schema, dict) or not isinstance(contract, dict):
        raise ContractError("canonical schema/template contract must be JSON objects")

    lock_path = graph_path.with_name(f".{graph_path.name}.register.lock")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with graph_operation_lock(graph_path, exclusive=True), lock_path.open("a+", encoding="utf-8") as lock:
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
        recovered = recover_pending_transaction(root, graph_path)
        graph_bytes_before = graph_path.read_bytes()
        graph = load_json(graph_path)
        if not isinstance(graph, dict) or not isinstance(graph.get("nodes"), list):
            raise ContractError("canonical graph must be an object with nodes[]")
        nodes = graph["nodes"]
        if not all(isinstance(item, dict) for item in nodes):
            raise ContractError("canonical graph nodes must be objects")

        requested_id = payload.get("graph_node_id")
        if requested_id is None and isinstance(payload.get("node"), dict):
            requested_id = payload["node"].get("graph_node_id")
        if requested_id is None and isinstance(payload.get("patch"), dict):
            requested_id = payload["patch"].get("graph_node_id")
        if not isinstance(requested_id, str) or not requested_id:
            raise ContractError("input requires graph_node_id")
        matches = [(index, item) for index, item in enumerate(nodes) if item.get("graph_node_id") == requested_id]
        if len(matches) > 1:
            raise ContractError(f"duplicate graph_node_id in canonical graph: {requested_id}")
        index = matches[0][0] if matches else None
        existing = copy.deepcopy(matches[0][1]) if matches else None
        node, explicit_updated_at = _request_node(payload, existing)
        if _node_id(node) != requested_id:
            raise ContractError("graph_node_id is immutable and must match the request identity")
        relative_path = _canonical_path(node, existing)
        # 新規 feature と kind 差替えによる feature 化の双方を gate する (dry-run も同じ経路)。
        if node.get("artifact_kind") == "feature" and (
            existing is None or existing.get("artifact_kind") != "feature"
        ):
            _assert_c14_macro_contract(node, root)
        artifact = contained(root / relative_path, root, must_exist=False)
        body = _body(payload, args.body_file, root, artifact, str(node["artifact_kind"]), existing)

        # Decide idempotency before generating an automatic update timestamp.
        preliminary_bytes = _artifact_bytes(node, body, schema)
        current_artifact_bytes = artifact.read_bytes() if artifact.is_file() else None
        changed = existing != node or current_artifact_bytes != preliminary_bytes
        if changed and existing is not None and not explicit_updated_at:
            node["updated_at"] = utc_now()
        artifact_bytes_after = _artifact_bytes(node, body, schema)

        proposed = copy.deepcopy(graph)
        if index is None:
            proposed["nodes"].append(node)
            operation = "added"
        else:
            proposed["nodes"][index] = node
            operation = "updated"
        violations = validator.validate(proposed["nodes"], repo_root=None, template_contract=contract)
        if violations:
            raise ContractError(f"proposed graph is invalid: {json.dumps(violations, ensure_ascii=False)}")

        graph_changed = graph != proposed
        artifact_changed = current_artifact_bytes != artifact_bytes_after
        if not graph_changed and not artifact_changed:
            return {
                "owner": "C02/run-dev-graph-node",
                "status": "preview" if args.dry_run else "applied",
                "operation": "noop",
                "idempotent": True,
                "graph_node_id": requested_id,
                "file_path": relative_path,
                "graph_revision_before": graph.get("graph_revision", 0),
                "graph_revision_after": graph.get("graph_revision", 0),
                "graph_sha256_before": _sha256(graph_bytes_before),
                "graph_sha256_after": _sha256(graph_bytes_before),
                "artifact_sha256_after": _sha256(artifact_bytes_after),
                "write_count": 0,
            }

        revision_before = graph.get("graph_revision", 0)
        if not isinstance(revision_before, int) or revision_before < 0:
            raise ContractError("graph_revision must be a non-negative integer")
        proposed["graph_revision"] = revision_before + 1
        receipt = {
            "owner": "C02/run-dev-graph-node",
            "status": "preview" if args.dry_run else "applied",
            "operation": operation,
            "idempotent": False,
            "graph_node_id": requested_id,
            "file_path": relative_path,
            "graph_revision_before": revision_before,
            "graph_revision_after": revision_before + 1,
            "graph_sha256_before": _sha256(graph_bytes_before),
            "graph_sha256_after": _sha256(
                (json.dumps(proposed, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode("utf-8")
            ),
            "artifact_sha256_after": _sha256(artifact_bytes_after),
            "write_count": 0 if args.dry_run else int(graph_changed) + int(artifact_changed),
        }
        if args.dry_run:
            return receipt

        artifact_existed = artifact.is_file()
        artifact_bytes_before = artifact.read_bytes() if artifact_existed else None
        graph_bytes_after = (
            json.dumps(proposed, ensure_ascii=False, sort_keys=True, indent=2) + "\n"
        ).encode("utf-8")
        prepare_transaction(
            root=root,
            graph_path=graph_path,
            graph_before=graph_bytes_before,
            graph_after=graph_bytes_after,
            artifact_path=artifact,
            artifact_before=artifact_bytes_before,
            artifact_after=artifact_bytes_after,
            graph_changed=graph_changed,
            artifact_changed=artifact_changed,
        )
        try:
            if artifact_changed:
                _atomic_bytes(artifact, artifact_bytes_after)
            if os.environ.get("DEV_GRAPH_TEST_INTERRUPT_AFTER_ARTIFACT") == "1":
                os._exit(99)
            artifact_violations = validator.artifact_findings([node], root, contract)
            if artifact_violations:
                raise ContractError(
                    f"generated artifact is invalid: {json.dumps(artifact_violations, ensure_ascii=False)}"
                )
            atomic_json(graph_path, proposed)
            finalize_transaction(root, graph_path)
        except BaseException:
            recover_pending_transaction(root, graph_path)
            raise
        receipt["graph_sha256_after"] = _sha256(graph_path.read_bytes())
        receipt["recovered_interrupted_transaction"] = recovered
        return receipt


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Atomically add or patch one dev-graph node")
    parser.add_argument("--repo-root", default=".")
    parser.add_argument("--graph")
    parser.add_argument("--input", help="JSON node/envelope/patch within the repository")
    parser.add_argument("--body-file", help="Markdown body without frontmatter, within the repository")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--operation", choices=("apply-lifecycle-request",))
    parser.add_argument("--request")
    parser.add_argument("--receipt")
    args = parser.parse_args(argv)
    try:
        if args.operation == "apply-lifecycle-request":
            if args.input or args.body_file or args.dry_run:
                raise ContractError(
                    "apply-lifecycle-request cannot be combined with node upsert arguments"
                )
            dump(_apply_lifecycle_request(args))
        else:
            if not args.input:
                raise ContractError("node upsert requires --input")
            if args.request or args.receipt:
                raise ContractError(
                    "--request/--receipt require --operation apply-lifecycle-request"
                )
            dump(_perform(args))
        return 0
    except (ContractError, OSError, json.JSONDecodeError, KeyError, TypeError, ValueError) as exc:
        dump({"valid": False, "error": str(exc), "write_count": 0})
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
# /// script
# name: validate-graph-schema
# purpose: Perform side-effect-free fail-closed validation of canonical dev-graph nodes, artifacts, and feature packages.
# inputs: ["argv: --graph FILE --repo-root PATH?"]
# outputs: ["stdout: JSON validation report"]
# requires-python = ">=3.10"
# dependencies: []
# contexts: [A, B, C, E]
# network: false
# write-scope: none
# ///
from __future__ import annotations

import argparse
import json
import re
import sys
from collections import Counter, defaultdict
from datetime import date, datetime
from pathlib import Path, PurePosixPath
from typing import Any
from urllib.parse import urlsplit

from _common import ContractError, contained, dump, load_json

PLUGIN_ROOT = Path(__file__).resolve().parents[1]
SCHEMA_PATH = PLUGIN_ROOT / "schemas" / "graph-node.schema.json"
TEMPLATE_CONTRACT_PATH = PLUGIN_ROOT / "templates" / "template-contract.json"
PHASES = {f"P{i:02d}" for i in range(1, 14)}
ROOT_BY_KIND = {
    "issue": "issues",
    "task": "tasks",
    "specification": "specs",
    "architecture": "architecture",
    "feature": "features",
    "document": "docs",
}


def nodes_of(data: Any) -> list[dict[str, Any]]:
    values = data.get("nodes") if isinstance(data, dict) else data
    if not isinstance(values, list) or not all(isinstance(item, dict) for item in values):
        raise ContractError("graph must be an array or an object with nodes[]")
    return values


def _is_type(value: Any, expected: str) -> bool:
    return {
        "null": value is None,
        "object": isinstance(value, dict),
        "array": isinstance(value, list),
        "string": isinstance(value, str),
        "boolean": isinstance(value, bool),
        "integer": isinstance(value, int) and not isinstance(value, bool),
        "number": isinstance(value, (int, float)) and not isinstance(value, bool),
    }.get(expected, True)


def _format_ok(value: str, expected: str) -> bool:
    try:
        if expected == "date":
            date.fromisoformat(value)
        elif expected == "date-time":
            datetime.fromisoformat(value.replace("Z", "+00:00"))
        elif expected == "uri":
            return bool(urlsplit(value).scheme)
    except ValueError:
        return False
    return True


def _schema_fallback(value: Any, schema: Any, root: dict[str, Any], path: str = "$") -> list[tuple[str, str]]:
    """Deterministic Draft 2020-12 subset used if jsonschema is unavailable."""
    if schema is True:
        return []
    if schema is False or not isinstance(schema, dict):
        return [(path, "value is forbidden" if schema is False else "invalid schema object")]
    findings: list[tuple[str, str]] = []
    reference = schema.get("$ref")
    if isinstance(reference, str):
        if not reference.startswith("#/"):
            return [(path, f"external schema reference is forbidden: {reference}")]
        target: Any = root
        try:
            for part in reference[2:].split("/"):
                target = target[part.replace("~1", "/").replace("~0", "~")]
        except (KeyError, TypeError):
            return [(path, f"unresolved schema reference: {reference}")]
        findings.extend(_schema_fallback(value, target, root, path))
    for child in schema.get("allOf", []):
        findings.extend(_schema_fallback(value, child, root, path))
    if "if" in schema and not _schema_fallback(value, schema["if"], root, path) and "then" in schema:
        findings.extend(_schema_fallback(value, schema["then"], root, path))
    expected = schema.get("type")
    if expected is not None:
        choices = expected if isinstance(expected, list) else [expected]
        if not any(_is_type(value, choice) for choice in choices):
            return findings + [(path, f"expected type {choices}, got {type(value).__name__}")]
    if "const" in schema and value != schema["const"]:
        findings.append((path, f"expected const {schema['const']!r}"))
    if "enum" in schema and value not in schema["enum"]:
        findings.append((path, f"not in enum {schema['enum']!r}"))
    if isinstance(value, str):
        if len(value) < schema.get("minLength", 0):
            findings.append((path, "string is shorter than minLength"))
        if "pattern" in schema and re.search(schema["pattern"], value) is None:
            findings.append((path, f"does not match {schema['pattern']}"))
        if "format" in schema and not _format_ok(value, schema["format"]):
            findings.append((path, f"invalid {schema['format']} format"))
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]:
            findings.append((path, "below minimum"))
        if "maximum" in schema and value > schema["maximum"]:
            findings.append((path, "above maximum"))
    if isinstance(value, list):
        if len(value) < schema.get("minItems", 0):
            findings.append((path, "too few items"))
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            findings.append((path, "too many items"))
        if schema.get("uniqueItems"):
            packed = [json.dumps(item, sort_keys=True, separators=(",", ":")) for item in value]
            if len(packed) != len(set(packed)):
                findings.append((path, "items are not unique"))
        items = schema.get("items")
        if isinstance(items, dict):
            for index, item in enumerate(value):
                findings.extend(_schema_fallback(item, items, root, f"{path}[{index}]"))
        if "contains" in schema and not any(not _schema_fallback(item, schema["contains"], root, path) for item in value):
            findings.append((path, "contains constraint is not satisfied"))
    if isinstance(value, dict):
        for key in schema.get("required", []):
            if key not in value:
                findings.append((path, f"missing required property {key}"))
        properties = schema.get("properties", {})
        for key, child in properties.items():
            if key in value:
                findings.extend(_schema_fallback(value[key], child, root, f"{path}.{key}"))
        additional = schema.get("additionalProperties", True)
        unknown = sorted(set(value) - set(properties))
        if additional is False and unknown:
            findings.append((path, f"unknown properties {unknown}"))
        elif isinstance(additional, dict):
            for key in unknown:
                findings.extend(_schema_fallback(value[key], additional, root, f"{path}.{key}"))
    return findings


def schema_findings(node: dict[str, Any], schema: dict[str, Any], index: int) -> list[dict[str, str]]:
    node_id = str(node.get("graph_node_id") or node.get("id") or f"nodes[{index}]")
    try:
        from jsonschema import Draft202012Validator, FormatChecker  # type: ignore
    except ImportError:
        raw = _schema_fallback(node, schema, schema)
    else:
        try:
            Draft202012Validator.check_schema(schema)
        except Exception as exc:
            raise ContractError(f"invalid canonical graph schema {SCHEMA_PATH}: {exc}") from exc
        validator = Draft202012Validator(schema, format_checker=FormatChecker())
        errors = sorted(
            validator.iter_errors(node),
            key=lambda err: (tuple(str(part) for part in err.absolute_path), err.message),
        )
        raw = [
            ("$" + "".join(f"[{part}]" if isinstance(part, int) else f".{part}" for part in error.absolute_path), error.message)
            for error in errors
        ]
    return [
        {"node": node_id, "code": "schema_violation", "detail": f"{path}: {detail}"}
        for path, detail in raw
    ]


def _scalar(raw: str) -> Any:
    value = raw.strip()
    try:
        return json.loads(value)
    except json.JSONDecodeError:
        if (value.startswith("'") and value.endswith("'")) or (value.startswith('"') and value.endswith('"')):
            return value[1:-1]
        return value


def frontmatter_of(path: Path) -> dict[str, Any]:
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError as exc:
        raise ContractError(f"cannot read artifact {path}: {exc}") from exc
    if not lines or lines[0].strip() != "---":
        raise ContractError(f"artifact has no YAML frontmatter: {path}")
    result: dict[str, Any] = {}
    for line in lines[1:]:
        if line.strip() == "---":
            return result
        match = re.match(r"^([A-Za-z_][A-Za-z0-9_-]*):(?:\s*(.*))?$", line)
        if match:
            result[match.group(1)] = _scalar(match.group(2) or "")
    raise ContractError(f"artifact frontmatter is not terminated: {path}")


def _repo_root_for(graph: Path, explicit: str | None) -> Path:
    if explicit:
        root = Path(explicit).expanduser().resolve(strict=True)
        contained(graph, root)
        return root
    resolved = graph.resolve(strict=True)
    for parent in resolved.parents:
        if parent.name == ".dev-graph":
            return parent.parent
    raise ContractError("--repo-root is required when --graph is outside the canonical .dev-graph tree")


def artifact_findings(
    nodes: list[dict[str, Any]], repo_root: Path | None, template_contract: dict[str, Any]
) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    required_frontmatter = set((template_contract.get("common_frontmatter") or {}).get("required") or [])
    for index, node in enumerate(nodes):
        node_id = str(node.get("graph_node_id") or node.get("id") or f"nodes[{index}]")
        kind = node.get("artifact_kind", node.get("kind"))
        raw_path = node.get("file_path")
        if kind in ROOT_BY_KIND and isinstance(raw_path, str):
            logical = PurePosixPath(raw_path)
            if logical.is_absolute() or ".." in logical.parts or not logical.parts or logical.parts[0] != ROOT_BY_KIND[kind]:
                findings.append({"node": node_id, "code": "path_parity_error", "detail": f"{kind} must be under {ROOT_BY_KIND[kind]}/"})
                continue
        if repo_root is None or not isinstance(raw_path, str):
            continue
        candidate = repo_root / raw_path
        try:
            # Missing canonical artifacts are readiness gaps, not containment
            # failures.  Resolve without requiring existence, then let the
            # is_file check below classify the missing artifact explicitly.
            artifact = contained(candidate, repo_root, must_exist=False)
        except (ContractError, OSError) as exc:
            findings.append({"node": node_id, "code": "artifact_path_invalid", "detail": str(exc)})
            continue
        if not artifact.is_file():
            findings.append({"node": node_id, "code": "artifact_missing", "detail": raw_path})
            continue
        try:
            frontmatter = frontmatter_of(artifact)
        except ContractError as exc:
            findings.append({"node": node_id, "code": "frontmatter_invalid", "detail": str(exc)})
            continue
        for key in sorted(required_frontmatter - set(frontmatter)):
            findings.append({"node": node_id, "code": "frontmatter_missing", "detail": key})
        for key in ("graph_node_id", "artifact_kind", "file_path", "template_id", "template_version"):
            if key in node and frontmatter.get(key) != node.get(key):
                findings.append({"node": node_id, "code": "frontmatter_parity_error", "detail": key})
    return findings


def domain_findings(nodes: list[dict[str, Any]]) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    ids: list[str] = []
    by_id: dict[str, dict[str, Any]] = {}
    for index, node in enumerate(nodes):
        node_id = node.get("graph_node_id") or node.get("id")
        loc = str(node_id or f"nodes[{index}]")
        if not isinstance(node_id, str) or not node_id:
            findings.append({"node": loc, "code": "missing_id", "detail": "graph_node_id required"})
            continue
        ids.append(node_id)
        by_id[node_id] = node
        kind = node.get("artifact_kind", node.get("kind"))
        if kind is not None and kind not in ROOT_BY_KIND:
            findings.append({"node": loc, "code": "invalid_kind", "detail": str(kind)})
        if node.get("status") not in {"draft", "active", "blocked", "done", "closed", "tombstoned"}:
            findings.append({"node": loc, "code": "invalid_status", "detail": str(node.get("status"))})
        dependencies = node.get("depends_on", [])
        if not isinstance(dependencies, list) or any(not isinstance(value, str) for value in dependencies):
            findings.append({"node": loc, "code": "invalid_dependencies", "detail": "depends_on must be string[]"})
        if node.get("tracker_binding") == "beads" and (node.get("github_publication") or {}).get("mode") != "local_only":
            findings.append({"node": loc, "code": "beads_publication", "detail": "beads requires local_only"})
        if node.get("tracker_binding") == "github" and node.get("beads_linkage") is not None:
            findings.append({"node": loc, "code": "binding_collision", "detail": "github cannot have beads_linkage"})
        if node.get("status") == "active":
            readiness = (node.get("implementation_readiness") or {}).get("status")
            if node.get("confirmation_status") != "confirmed" or node.get("evaluation_status") != "pass" or readiness != "complete":
                findings.append({"node": loc, "code": "active_not_ready", "detail": "active requires confirmed/pass/complete"})
        if node.get("tracker_binding") == "repo-config-default":
            findings.append({"node": loc, "code": "unresolved_tracker_binding", "detail": "durable graph cannot retain repo-config-default"})
    for duplicate, count in Counter(ids).items():
        if count > 1:
            findings.append({"node": duplicate, "code": "duplicate_id", "detail": str(count)})
    reference_fields = ("depends_on", "related_nodes", "architecture_refs")
    for index, node in enumerate(nodes):
        node_id = str(node.get("graph_node_id") or node.get("id") or f"nodes[{index}]")
        for field in reference_fields:
            for reference in node.get(field, []) if isinstance(node.get(field, []), list) else []:
                if reference not in by_id:
                    code = "dangling_dependency" if field == "depends_on" else "dangling_reference"
                    findings.append({"node": node_id, "code": code, "detail": f"{field}:{reference}"})
        parent = node.get("parent_feature")
        if isinstance(parent, str) and parent not in by_id:
            findings.append({"node": node_id, "code": "dangling_reference", "detail": f"parent_feature:{parent}"})

    state: dict[str, int] = {}

    def visit(node_id: str) -> None:
        if state.get(node_id) == 1:
            findings.append({"node": node_id, "code": "dependency_cycle", "detail": node_id})
            return
        if state.get(node_id) == 2:
            return
        state[node_id] = 1
        dependencies = by_id[node_id].get("depends_on", [])
        for dependency in dependencies if isinstance(dependencies, list) else []:
            if dependency in by_id:
                visit(dependency)
        state[node_id] = 2

    for node_id in by_id:
        visit(node_id)

    children: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for node in nodes:
        if isinstance(node.get("parent_feature"), str):
            children[node["parent_feature"]].append(node)
    order = {phase: int(phase[1:]) for phase in PHASES}
    for feature_id, feature in ((node_id, node) for node_id, node in by_id.items() if node.get("artifact_kind") == "feature"):
        members = children.get(feature_id, [])
        if members or feature.get("status") == "done":
            packages = {member.get("feature_package_id") for member in members}
            phases = [member.get("phase_ref") for member in members]
            if packages == {None} or len(packages) != 1 or set(phases) != PHASES or len(members) != 13:
                findings.append({"node": feature_id, "code": "feature_package_not_exact_13", "detail": f"count={len(members)} phases={sorted(str(value) for value in set(phases))}"})
        for child in members:
            current = order.get(child.get("phase_ref"), 0)
            for dependency in child.get("depends_on", []):
                target = by_id.get(dependency, {})
                if target.get("parent_feature") == feature_id and order.get(target.get("phase_ref"), 0) >= current:
                    findings.append({"node": str(child.get("graph_node_id") or child.get("id") or "?"), "code": "non_forward_phase_dependency", "detail": dependency})
        if feature.get("status") == "done":
            if any(member.get("status") != "done" for member in members):
                findings.append({"node": feature_id, "code": "premature_feature_done", "detail": "all 13 children must be done"})
            for phase in {"P07", "P10", "P11"}:
                child = next((member for member in members if member.get("phase_ref") == phase), {})
                if not (child.get("completion_evidence") or {}).get("evidence_refs"):
                    findings.append({"node": feature_id, "code": "feature_evidence_missing", "detail": phase})
    return findings


def validate(
    nodes: list[dict[str, Any]], schema: dict[str, Any] | None = None,
    *, repo_root: Path | None = None, template_contract: dict[str, Any] | None = None,
) -> list[dict[str, str]]:
    canonical_schema = schema or load_json(SCHEMA_PATH)
    if not isinstance(canonical_schema, dict):
        raise ContractError(f"canonical graph schema must be an object: {SCHEMA_PATH}")
    contract = template_contract or load_json(TEMPLATE_CONTRACT_PATH)
    if not isinstance(contract, dict):
        raise ContractError(f"template contract must be an object: {TEMPLATE_CONTRACT_PATH}")
    findings = [item for index, node in enumerate(nodes) for item in schema_findings(node, canonical_schema, index)]
    findings.extend(domain_findings(nodes))
    findings.extend(artifact_findings(nodes, repo_root, contract))
    return sorted(findings, key=lambda item: (item["node"], item["code"], item["detail"]))


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--graph",
        required=True,
        help="graph JSON path、または '-' で stdin から preview graph を読む (dry-run 用)",
    )
    parser.add_argument("--repo-root")
    args = parser.parse_args()
    if args.graph == "-":
        # dry-run preview 検証: 管理対象 repo へ一時ファイルを書かせないための stdin 経路。
        # --graph FILE は contained(graph, root) を要求するため、preview を検証するには
        # repo 内へ書くしかなく「dry-run write 0」契約と矛盾していた (C14 OUT3)。
        if not args.repo_root:
            raise ContractError("--repo-root is required when reading a preview graph from stdin")
        repo_root = Path(args.repo_root).expanduser().resolve(strict=True)
        nodes = nodes_of(json.loads(sys.stdin.read()))
    else:
        graph = Path(args.graph).expanduser().resolve(strict=True)
        repo_root = _repo_root_for(graph, args.repo_root)
        nodes = nodes_of(load_json(graph))
    violations = validate(nodes, repo_root=repo_root)
    missing = sorted({
        item["detail"] for item in violations
        if item["code"] in {"frontmatter_missing", "artifact_missing"}
        or (item["code"] == "schema_violation" and "required property" in item["detail"])
    })
    dump({
        "valid": not violations,
        "implementation_readiness": "complete" if not violations else "incomplete",
        "missing_sections": missing,
        "schema": str(SCHEMA_PATH),
        "violations": violations,
    })
    return 0 if not violations else 1


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ContractError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        raise SystemExit(2)

